--1. Revenue generated by each channel
SELECT channel, SUM(revenue_first_90_days) AS total_revenue
FROM signups_clean
GROUP BY channel;


--2.1 Campaign popularity
SELECT channel, campaign, COUNT(user_id) AS signups
FROM signups_clean
WHERE source_type = 'subscribed'
GROUP BY channel, campaign
ORDER BY signups DESC;

-- 2.2
SELECT channel, campaign,
       COUNT(*) AS signups,
       COUNT(*) FILTER (WHERE subscribing) AS subscribers
FROM signups_clean
WHERE campaign IS NOT NULL
GROUP BY channel, campaign
ORDER BY subscribers DESC;

-- Total subscribers from campaign
SELECT COUNT(*) FILTER (WHERE subscribing) AS subscribers
FROM signups_clean
WHERE campaign IS NOT NULL
ORDER BY subscribers DESC;

--3. Lowest cost per signup
WITH spend AS (
    SELECT channel, campaign, SUM(spend) AS total_spend
    FROM ad_spend_clean
    GROUP BY channel, campaign
),
su AS (
    SELECT channel, campaign, COUNT(*) AS signups
    FROM signups_clean
    WHERE campaign IS NOT NULL
    GROUP BY channel, campaign
)
SELECT s.channel, s.campaign, s.total_spend, su.signups,
       ROUND(s.total_spend / NULLIF(su.signups, 0), 2) AS cost_per_signup
FROM spend s
JOIN su USING (channel, campaign)
ORDER BY cost_per_signup;

--4. Costs and customer conversion breakdown
WITH spend AS (
    SELECT channel, campaign, SUM(spend) AS total_spend
    FROM ad_spend_clean
    GROUP BY channel, campaign
),
outcomes AS (
    SELECT channel, campaign,
           COUNT(*) AS signups,
           COUNT(*) FILTER (WHERE subscribing) AS subscribers
    FROM signups_clean
    WHERE campaign IS NOT NULL
    GROUP BY channel, campaign
)
SELECT s.channel, s.campaign,
       ROUND(s.total_spend / NULLIF(o.signups, 0), 2) AS cost_per_signup,
       ROUND(100.0 * o.subscribers / NULLIF(o.signups, 0), 2) AS customer_conversion_rate,
       ROUND(s.total_spend / NULLIF(o.subscribers, 0), 2) AS cost_per_customer
FROM spend s
JOIN outcomes o USING (channel, campaign)
ORDER BY cost_per_signup;

--5. Conversion rate per channel
SELECT channel,
       COUNT(*) AS signups,
       COUNT(*) FILTER (WHERE subscribing) AS subscribers,
       ROUND(100.0 * COUNT(*) FILTER (WHERE subscribing) / COUNT(*), 2) AS customer_conversion_rate
FROM signups_clean
WHERE source_type = 'subscribed'
GROUP BY channel
ORDER BY channel;

--6. Unpaid channel revenue
SELECT channel,
SUM(revenue_first_90_days) AS revenue
FROM signups_clean
WHERE channel IN ('organic', 'referral')
AND subscribing IS true
GROUP BY channel;

--7. Paid vs unpaid channels
SELECT CASE WHEN channel IN ('paid_search', 'paid_social', 'display', 'affiliate') THEN 'PAID'
            WHEN channel IN ('referral', 'organic') THEN 'UNPAID'
            ELSE 'UNKNOWN'
       END AS channel_type,
       COUNT(*) AS signups,
       COUNT(*) FILTER (WHERE subscribing) AS subscribers,
       SUM(revenue_first_90_days) AS total_revenue
FROM signups_clean
GROUP BY 1
ORDER BY total_revenue DESC;
